import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * LARGE-SCALE ROBOTICS.
 *
 * The final track, and the honesty checkpoint of the whole curriculum. Scaling a
 * robot up is not making more of the same: mass grows faster than strength,
 * torque grows faster than actuator capability, and stored energy grows faster
 * than any safety margin you carried over from a small machine. Every lesson
 * here computes those facts rather than asserting them, and the last one answers
 * the question this project is named after - directly, with numbers.
 *
 * Order: scaling laws -> power and actuation at scale -> structures at scale ->
 * safety at scale -> programmes, teams and economics -> the frontier and the
 * Jaeger question.
 */
